<template><div class="slide-up pb-8"><StepHeader :step="5" eyebrow="Оплата" title="Выбери способ оплаты" description="Оплата подключается через защищённого провайдера. Сейчас заказ будет создан со статусом ожидания." /><div class="space-y-3"><button v-for="item in methods" :key="item.id" class="w-full rounded-2xl border bg-white p-4 text-left transition" :class="order.draft.paymentMethod === item.id ? 'border-sage ring-2 ring-sage/10' : 'border-line'" @click="order.setPaymentMethod(item.id)"><div class="flex items-center justify-between"><div><p class="font-bold">{{ item.name }}</p><p class="mt-1 text-xs text-ink/45">{{ item.description }}</p></div><span class="flex h-5 w-5 items-center justify-center rounded-full border" :class="order.draft.paymentMethod === item.id ? 'border-sage bg-sage' : 'border-line'"><span v-if="order.draft.paymentMethod === item.id" class="h-2 w-2 rounded-full bg-white" /></span></div></button></div><div class="mt-6 rounded-2xl bg-mint p-5"><p class="text-sm text-ink/55">К оплате</p><p class="mt-1 text-3xl font-bold text-sage">{{ formatUsd(order.draft.totalPrice) }}</p><p class="mt-3 text-xs leading-5 text-ink/55">Статус оплаты: ожидается подтверждение. Мы не считаем заказ оплаченным без ответа платёжной системы.</p></div><p v-if="error" class="mt-3 text-sm text-terracotta">{{ error }}</p><BackNext back-to="/measurements" :disabled="!order.draft.paymentMethod" @next="goNext" /></div></template>
<script setup lang="ts">import { formatUsd } from '~/utils/pricing'; import type { PaymentMethod } from '~/types/order'; const order = useOrderStore(); const error = ref(''); const methods: { id: PaymentMethod; name: string; description: string }[] = [{ id: 'click', name: 'Click', description: 'Оплата через Click' }, { id: 'payme', name: 'Payme', description: 'Оплата через Payme' }, { id: 'uzum', name: 'Uzum', description: 'Оплата через Uzum' }, { id: 'visa', name: 'Visa', description: 'Банковская карта Visa' }]; function goNext(): void { if (!order.draft.paymentMethod) { error.value = 'Выберите способ оплаты'; return } navigateTo('/cart') }</script>
